<?php
declare(strict_types=1);
require_once __DIR__.'/../vendor/autoload.php';
use MiniErp\Fiscal\TaxRuleResolver;
use MiniErp\Repositories\{FiscalOperationRepository,MariaDbTaxRuleRepository};
use MiniErp\Services\{FiscalDanfeException,FiscalDanfePreviewService};
if(session_status()!==PHP_SESSION_ACTIVE)session_start();$tenantId=(int)($_SESSION['erp_tenant_id']??0);$userId=(int)($_SESSION['erp_user_id']??0);if($tenantId<1||$userId<1){http_response_code(401);exit('Sessão expirada.');}session_write_close();$orderId=filter_input(INPUT_GET,'order_id',FILTER_VALIDATE_INT)?:0;$documentId=filter_input(INPUT_GET,'document_id',FILTER_VALIDATE_INT)?:0;
try{$cfg=require __DIR__.'/../config.php';$d=$cfg['db'];$main=new PDO("mysql:host={$d['host']};port={$d['port']};dbname={$d['database']};charset=utf8mb4",$d['username'],$d['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$query=$main->prepare('SELECT db_name FROM tenants WHERE id=?');$query->execute([$tenantId]);$db=(string)$query->fetchColumn();if(!preg_match('/^mini_erp_tenant_[1-9]\d*$/',$db))throw new FiscalDanfeException('PREVIEW_TENANT_INVALID','Empresa não encontrada.');$pdo=new PDO("mysql:host={$d['host']};port={$d['port']};dbname={$db};charset=utf8mb4",$d['username'],$d['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$operations=new FiscalOperationRepository($pdo,$tenantId);if($documentId>0){$document=$operations->document($documentId);$orderId=(int)$document['source_order_id'];}if($orderId<1)throw new FiscalDanfeException('PREVIEW_ORDER_NOT_FOUND','Pedido ou documento não encontrado para esta empresa.');error_log('FISCAL_CENTER_ACTION tenant='.$tenantId.' document_id='.$documentId.' order_id='.$orderId.' action=preview stage=resolve status=OK');$service=new FiscalDanfePreviewService($pdo,$operations,new TaxRuleResolver(new MariaDbTaxRuleRepository($pdo,$tenantId)),__DIR__.'/../storage/fiscal/danfe-preview');$result=$service->render((int)$orderId);$name=str_replace(['"',"\r","\n"],'',(string)$result['filename']);header('Content-Type: application/pdf');header('Content-Disposition: inline; filename="'.$name.'"');header('Content-Length: '.strlen($result['bytes']));header('X-Content-Type-Options: nosniff');header('Cache-Control: private, no-store');echo$result['bytes'];}catch(FiscalDanfeException$e){http_response_code(422);header('Content-Type: text/html; charset=utf-8');echo'<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Prévia DANFE indisponível</title><body style="font-family:system-ui;padding:32px"><h1>Não foi possível gerar a prévia DANFE.</h1><p>'.htmlspecialchars($e->getMessage(),ENT_QUOTES,'UTF-8').'</p><button onclick="window.close()">Fechar</button></body></html>';}catch(Throwable$e){error_log('DANFE_PREVIEW_FAILED tenant='.$tenantId.' document_id='.$documentId.' order_id='.$orderId.' type='.get_class($e));http_response_code(422);header('Content-Type: text/html; charset=utf-8');echo'<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Prévia DANFE indisponível</title><body style="font-family:system-ui;padding:32px"><h1>Não foi possível gerar a prévia DANFE.</h1><p>Revise os dados fiscais do pedido e tente novamente.</p><button onclick="window.close()">Fechar</button></body></html>';}
